182	    /// Returns the supertype between `self` and `other`, or `Type::Any` if they're unrelated
183	    pub fn widen(self, other: Type) -> Type {
184	        /// Returns supertype of arguments without creating a `oneof`, or falling back to `any`
185	        /// (unless one or both of the arguments are `any`)
186	        fn flat_widen(lhs: Type, rhs: Type) -> Result<Type, (Type, Type)> {
187	            Ok(match (lhs, rhs) {
188	                (lhs, rhs) if lhs == rhs => lhs,
189	                (Type::Any, _) | (_, Type::Any) => Type::Any,
190	                // (int, int) and (float, float) cases are already handled by the first match arm
191	                (
192	                    Type::Int | Type::Float | Type::Number,
193	                    Type::Int | Type::Float | Type::Number,
194	                ) => Type::Number,
195	
196	                (Type::Glob, Type::String) | (Type::String, Type::Glob) => Type::String,
197	                (Type::Record(this), Type::Record(that)) => {
198	                    Type::Record(widen_collection(this, that))
199	                }
200	                (Type::Table(this), Type::Table(that)) => Type::Table(widen_collection(this, that)),
201	                (Type::List(list_item), Type::Table(table))
202	                | (Type::Table(table), Type::List(list_item)) => {
203	                    let item = match *list_item {
204	                        Type::Record(record) => Type::Record(widen_collection(record, table)),
205	                        list_item => Type::one_of([list_item, Type::Record(table)]),
206	                    };
207	                    Type::List(Box::new(item))
208	                }
209	                (Type::List(lhs), Type::List(rhs)) => Type::list(lhs.widen(*rhs)),
210	                (t, u) => return Err((t, u)),
211	            })
212	        }
213	        fn widen_collection(
214	            lhs: Box<[(String, Type)]>,
215	            rhs: Box<[(String, Type)]>,
216	        ) -> Box<[(String, Type)]> {
217	            if lhs.is_empty() || rhs.is_empty() {
218	                return [].into();
219	            }
220	            let (small, big) = match lhs.len() <= rhs.len() {
221	                true => (lhs, rhs),
222	                false => (rhs, lhs),
223	            };
224	            small
225	                .into_iter()
226	                .filter_map(|(col, typ)| {
227	                    big.iter()
228	                        .find_map(|(b_col, b_typ)| (&col == b_col).then(|| b_typ.clone()))
229	                        .map(|b_typ| (col, typ, b_typ))
230	                })
231	                .map(|(col, t, u)| (col, t.widen(u)))
232	                .collect()
233	        }
