235	        fn oneof_add(oneof: &mut Vec<Type>, mut t: Type) {
236	            if oneof.contains(&t) {
237	                return;
238	            }
239	
240	            for one in oneof.iter_mut() {
241	                match flat_widen(std::mem::replace(one, Type::Any), t) {
242	                    Ok(one_t) => {
243	                        *one = one_t;
244	                        return;
245	                    }
246	                    Err((one_, t_)) => {
247	                        *one = one_;
248	                        t = t_;
249	                    }
250	                }
251	            }
252	
253	            oneof.push(t);
254	        }
255	
256	        let tu = match flat_widen(self, other) {
257	            Ok(t) => return t,
258	            Err(tu) => tu,
259	        };
260	
261	        match tu {
262	            (Type::OneOf(ts), Type::OneOf(us)) => {
263	                let (big, small) = match ts.len() >= us.len() {
264	                    true => (ts, us),
265	                    false => (us, ts),
266	                };
267	                let mut out = big.into_vec();
268	                for t in small.into_iter() {
269	                    oneof_add(&mut out, t);
270	                }
271	                Type::one_of(out)
272	            }
273	            (Type::OneOf(oneof), t) | (t, Type::OneOf(oneof)) => {
274	                let mut out = oneof.into_vec();
275	                oneof_add(&mut out, t);
276	                Type::one_of(out)
277	            }
278	            (this, other) => Type::one_of([this, other]),
279	        }
280	    }
