282	    /// Returns the supertype of all types within `it`. Short-circuits on, and falls back to, `Type::Any`.
283	    pub fn supertype_of(it: impl IntoIterator<Item = Type>) -> Option<Self> {
284	        let mut it = it.into_iter();
285	        it.next().and_then(|head| {
286	            it.try_fold(head, |acc, e| match acc.widen(e) {
287	                Type::Any => None,
288	                r => Some(r),
289	            })
290	        })
291	    }
